/** Art for the Ice Cream Man clickventure — Pavlos's illustrations, bundled.
 *  ICE_CREAM_ASSETS maps each panel to a ready-to-use img `src`.
 *
 *  Everything stays inline: no external URLs, no network (Obsidian forbids
 *  runtime-fetched promo art) — and the community-plugin installer only ever
 *  copies main.js / manifest.json / styles.css out of a release, so shipping the
 *  art as sibling files would simply not install. Hence base64 in the bundle.
 *
 *  Encoded from the 1024px JPG masters at **640px, WEBP q70** — ~60 KB each,
 *  ~563 KB of base64 across the seven panels. The masters are ~255 KB each
 *  (~2.4 MB base64), which would have quadrupled main.js for art shown in a
 *  ~360px slot. Re-encode from the masters with cwebp if the slot ever grows:
 *      cwebp -resize 640 640 -q 70 "<master>.jpg" -o <panel>.webp
 *
 *  Generated file — the base64 lines are not hand-editable. */

import type { IceCreamPanelKey } from "./ice-cream-man.ts";

export const ICE_CREAM_ASSETS: Record<IceCreamPanelKey, string> = {
  /** The truck, window open, the Ice Cream Man mid-welcome.
   *  Source: "Whatll it be.jpg" — 640px, WEBP q70. */
  greeting: "data:image/webp;base64,",
  /** The chocolate cone, handed over.
   *  Source: "Chocolate.jpg" — 640px, WEBP q70. */
  coneChocolate: "data:image/webp;base64,",
  /** The vanilla cone, handed over.
   *  Source: "Vanilla.jpg" — 640px, WEBP q70. */
  coneVanilla: "data:image/webp;base64,",
  /** The raspberry swirl cone, handed over.
   *  Source: "Raspberry swirl.jpg" — 640px, WEBP q70. */
  coneRaspberry: "data:image/webp;base64,",
  /** The collection basket, held out over the counter.
   *  Source: "Donations.jpg" — 640px, WEBP q70. */
  basket: "data:image/webp;base64,",
  /** Fists up, the whole queue cheering — the yes.
   *  Source: "Celebrate.jpg" — 640px, WEBP q70. */
  celebrate: "data:image/webp;base64,",
  /** A warm wave off — the no, taken kindly.
   *  Source: "Goodbye.jpg" — 640px, WEBP q70. */
  goodbye: "data:image/webp;base64,",
  /** A hand on the heart — the PRO ending, in place of the ask.
   *  Source: "Gratitude.jpg" — 640px, WEBP q70. */
  gratitude: "data:image/webp;base64,",
};
